<? if (!defined("B_PROLOG_INCLUDED") || B_PROLOG_INCLUDED !== true) die();/** @var array $arParams *//** @var array $arResult *//** @global CMain $APPLICATION *//** @global CUser $USER *//** @global CDatabase $DB *//** @var CBitrixComponentTemplate $this *//** @var string $templateName *//** @var string $templateFile *//** @var string $templateFolder *//** @var string $componentPath *//** @var CBitrixComponent $component */$this->setFrameMode(true);//echo "<pre>"; print_r($arResult); echo "</pre>";?><div class="slider_area_1">    <? foreach ($arResult["ITEMS"] as $arItem): ?>        <?        $this->AddEditAction($arItem['ID'], $arItem['EDIT_LINK'], CIBlock::GetArrayByID($arItem["IBLOCK_ID"], "ELEMENT_EDIT"));        $this->AddDeleteAction($arItem['ID'], $arItem['DELETE_LINK'], CIBlock::GetArrayByID($arItem["IBLOCK_ID"], "ELEMENT_DELETE"), array("CONFIRM" => GetMessage('CT_BNL_ELEMENT_DELETE_CONFIRM')));        $arProps = $arItem['PROPERTIES'];        if ($arProps["ACTUAL"]["~VALUE"] != 'Нет' && !empty($arItem["DETAIL_PICTURE"])) {            ?>            <div class="slider_area__item" id="<?= $this->GetEditAreaId($arItem['ID']); ?>">                <? if ($arParams["DISPLAY_PICTURE"] != "N" && is_array($arItem["DETAIL_PICTURE"])): ?>                    <? if (!$arParams["HIDE_LINK_WHEN_NO_DETAIL"] || ($arItem["DETAIL_TEXT"] && $arResult["USER_HAVE_ACCESS"])): ?>                        <a href="<?= $arItem["DETAIL_PAGE_URL"] ?>"><img                                    class="slider_area__img1"                                    border="0"                                    src="<?= $arItem["DETAIL_PICTURE"]["SRC"] ?>"                                    alt="<?= $arItem["DETAIL_PICTURE"]["ALT"] ?>"                                    title="<?= $arItem["DETAIL_PICTURE"]["TITLE"] ?>"                            /></a>                    <? else: ?>                        <img                                class="slider_area__img"                                border="0"                                src="<?= $arItem["DETAIL_PICTURE"]["SRC"] ?>"                                alt="<?= $arItem["DETAIL_PICTURE"]["ALT"] ?>"                                title="<?= $arItem["DETAIL_PICTURE"]["TITLE"] ?>"                        />                    <? endif; ?>                <? endif ?>                <? if (!empty($arProps['DESCRIPTION']['VALUE'])): ?>                    <div class="header__text">                    <span class="header__text-middle">                        <? echo $arProps['DESCRIPTION']['VALUE']['TEXT']; ?>                    </span>                    </div>                <? endif; ?>            </div>        <? } ?>    <? endforeach; ?></div><script type="text/javascript">    $(document).ready(function () {        $('.slider_area_1').slick({            arrows: false,            dots: true,            autoplay: true,            autoplaySpeed: 3000,            infinite: true,            speed: 500,            fade: true,            cssEase: 'linear'        });    });</script>